3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Assigns the owner's deterministic {@code householdId}: the first 12 hex characters of
12	 * SHA-256 over {@code normalizedLastName + '|' + postcode}. Because the value is derived
13	 * purely from the (last name, postcode) pair, every owner sharing that pair computes the
14	 * same identifier automatically — the household is keyed on the pair, not created by an
15	 * explicit opt-in.
16	 *
17	 * <p>The last name is normalized (compared case-insensitively with collapsed whitespace)
18	 * before hashing; the postcode is used verbatim, treated as empty when absent. So two
19	 * owners with the same last name and postcode always share a household, regardless of
20	 * creation order or the {@code sharesHousehold} flag (which now only bypasses the
21	 * household-duplicate block — see {@link EnsureUniqueHousehold}).
22	 *
23	 * <p>Runs after {@link BuildOwner} (which produces the {@link Owner}) and before
24	 * {@link EnsureUniqueHousehold}/{@link SaveOwner}; it mutates the built owner in place
25	 * (see {@code @Val} semantics). The computed id feeds duplicate detection (via the
26	 * {@code identityKey}) and the household-size count.
27	 */
28	public class AssignHousehold {
29	
30	    public void service(@Val Owner owner) {
31	        String lastName = normalize(owner.getLastName());
32	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
33	        owner.setHouseholdId(householdId(lastName, postcode));
34	    }
35	
36	    /** Deterministic 12-char hex id over the normalized last name and postcode. */
37	    private static String householdId(String lastName, String postcode) {
38	        return sha256hex(lastName + "|" + postcode).substring(0, 12);
39	    }
40	
41	    private static String sha256hex(String value) {
42	        try {
43	            byte[] digest = MessageDigest.getInstance("SHA-256")
44	                    .digest(value.getBytes(StandardCharsets.UTF_8));
45	            StringBuilder sb = new StringBuilder(digest.length * 2);
46	            for (byte b : digest) {
47	                sb.append(String.format("%02x", b));
48	            }
49	            return sb.toString();
50	        }
51	        catch (NoSuchAlgorithmException e) {
